// Package postgres contains the persistence adapters. Queries are generated by
// sqlc from migrations + queries/*.sql; this file only maps between the
// generated row types and the domain types.
package postgres

import (
	"context"
	"encoding/hex"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/gjovanovicst/ai-engineering-platform/internal/adapters/postgres/pgstore"
	"github.com/gjovanovicst/ai-engineering-platform/internal/app/auth"
	"github.com/gjovanovicst/ai-engineering-platform/internal/platform/db"
)

// SessionStore implements auth.SessionStore on top of PostgreSQL.
type SessionStore struct {
	pool *pgxpool.Pool
	q    *pgstore.Queries
}

// NewSessionStore wires the store to a pool.
func NewSessionStore(pool *pgxpool.Pool) *SessionStore {
	return &SessionStore{pool: pool, q: pgstore.New(pool)}
}

var _ auth.SessionStore = (*SessionStore)(nil)

// Create inserts a new session.
func (s *SessionStore) Create(ctx context.Context, sess auth.Session) error {
	_, err := s.q.CreateSession(ctx, createParams(sess))
	return err
}

// ByRefreshHash returns the session behind a hashed refresh token, including
// revoked ones so that reuse can be detected.
func (s *SessionStore) ByRefreshHash(ctx context.Context, hash []byte) (auth.Session, error) {
	row, err := s.q.SessionByRefreshHash(ctx, hash)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return auth.Session{}, auth.ErrInvalidToken
		}
		return auth.Session{}, err
	}
	return fromRow(row), nil
}

// Rotate revokes the old session and inserts the next one in a transaction.
func (s *SessionStore) Rotate(ctx context.Context, oldID string, next auth.Session, at time.Time) error {
	return db.WithTx(ctx, s.pool, func(ctx context.Context, tx pgx.Tx) error {
		q := s.q.WithTx(tx)
		reason := "rotated"
		if err := q.RotateSession(ctx, pgstore.RotateSessionParams{
			ID:            toUUID(oldID),
			RevokedAt:     toTS(at),
			RevokedReason: &reason,
		}); err != nil {
			return err
		}
		_, err := q.CreateSession(ctx, createParams(next))
		return err
	})
}

// RevokeSession ends one session (logout).
func (s *SessionStore) RevokeSession(ctx context.Context, id, reason string, at time.Time) error {
	return s.q.RevokeSession(ctx, pgstore.RevokeSessionParams{
		ID:            toUUID(id),
		RevokedAt:     toTS(at),
		RevokedReason: &reason,
	})
}

// RevokeAllForUser ends every active session of a user (reuse detection,
// password reset, "sign out everywhere").
func (s *SessionStore) RevokeAllForUser(ctx context.Context, userID, reason string, at time.Time) error {
	return s.q.RevokeAllForUser(ctx, pgstore.RevokeAllForUserParams{
		UserID:        toUUID(userID),
		RevokedAt:     toTS(at),
		RevokedReason: &reason,
	})
}

// Touch records that a session was used.
func (s *SessionStore) Touch(ctx context.Context, id string, at time.Time) error {
	return s.q.TouchSession(ctx, pgstore.TouchSessionParams{ID: toUUID(id), LastUsedAt: toTS(at)})
}

func createParams(sess auth.Session) pgstore.CreateSessionParams {
	p := pgstore.CreateSessionParams{
		UserID:      toUUID(sess.UserID),
		OrgID:       toUUID(sess.OrgID),
		RefreshHash: sess.RefreshHash,
		Platform:    string(sess.Platform),
		ExpiresAt:   toTS(sess.ExpiresAt),
		CreatedAt:   toTS(sess.CreatedAt),
	}
	if sess.Role != "" {
		role := sess.Role
		p.Role = &role
	}
	return p
}

func fromRow(row pgstore.Session) auth.Session {
	sess := auth.Session{
		ID:          uuidString(row.ID),
		UserID:      uuidString(row.UserID),
		OrgID:       uuidString(row.OrgID),
		RefreshHash: row.RefreshHash,
		Platform:    auth.Platform(row.Platform),
		ExpiresAt:   row.ExpiresAt.Time,
		CreatedAt:   row.CreatedAt.Time,
	}
	if row.Role != nil {
		sess.Role = *row.Role
	}
	if row.RevokedAt.Valid {
		t := row.RevokedAt.Time
		sess.RevokedAt = &t
	}
	if row.LastUsedAt.Valid {
		t := row.LastUsedAt.Time
		sess.LastUsedAt = &t
	}
	return sess
}

func toUUID(v string) pgtype.UUID {
	var u pgtype.UUID
	if v == "" {
		return u
	}
	_ = u.Scan(v)
	return u
}

func toTS(t time.Time) pgtype.Timestamptz {
	if t.IsZero() {
		return pgtype.Timestamptz{}
	}
	return pgtype.Timestamptz{Time: t, Valid: true}
}

func uuidString(u pgtype.UUID) string {
	if !u.Valid {
		return ""
	}
	b := u.Bytes
	var out [36]byte
	hex.Encode(out[0:8], b[0:4])
	out[8] = '-'
	hex.Encode(out[9:13], b[4:6])
	out[13] = '-'
	hex.Encode(out[14:18], b[6:8])
	out[18] = '-'
	hex.Encode(out[19:23], b[8:10])
	out[23] = '-'
	hex.Encode(out[24:36], b[10:16])
	return string(out[:])
}
